// Atlas de Parasitología: cliente estático.
const DB_NAME='atlas-parasitologia', STORE='atlas', BLOB_STORE='images';
const TAXON_FIELDS=['granGroup','group','subgroup','family','subfamily','genus','species'];
const FIELD_LABELS={commonName:'Nombre vulgar',importance:'Importancia',location:'Localización',definitiveHost:'Hospedador definitivo',intermediateHost:'Hospedador intermediario',paratenicHost:'Hospedador paraténico',cycle:'Ciclo biológico',ppp:'PPP / período prepatente',morphologyGeneral:'Morfología general',morphologyMale:'Morfología macho',morphologyFemale:'Morfología hembra',egg:'Huevo',infectiveForm:'Forma infectante',description:'Descripción',observations:'Observaciones'};
const COLUMNS=[['level','Nivel'],['granGroup','Gran grupo'],['group','Grupo'],['subgroup','Subgrupo'],['family','Familia'],['subfamily','Subfamilia'],['genus','Género'],['species','Especie'],['commonName','Nombre vulgar'],['definitiveHost','Hospedador definitivo'],['intermediateHost','Hospedador intermediario'],['paratenicHost','Hospedador paraténico'],['location','Localización'],['importance','Importancia'],['cycle','Ciclo biológico'],['ppp','PPP'],['infectiveForm','Forma infectante'],['morphologyGeneral','Morfología general'],['morphologyMale','Morfología macho'],['morphologyFemale','Morfología hembra'],['egg','Huevo'],['description','Descripción'],['observations','Observaciones']];
const EXPORT_COLUMNS=[['level','Nivel'],['granGroup','Gran grupo'],['group','Grupo'],['subgroup','Subgrupo'],['family','Familia'],['subfamily','Subfamilia'],['genus','Género'],['species','Especie'],...Object.entries(FIELD_LABELS),['sourceTrace','Trazabilidad de fuentes']];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let state, seed, currentId=null, currentView='atlas', sort={key:'scientificName',dir:1}, filters={tableSearch:'',group:'all',level:'all',galleryType:'all'}, cloud=null;

const escapeHtml=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const slug=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const short=s=>s?.length>155?`${s.slice(0,155)}…`:s;
const now=()=>new Date().toISOString();
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>t.classList.remove('show'),2600)}
function scientific(node){if(node.level==='species'){const g=node.path.find(x=>x.level==='genus')?.name||'';return `${g} ${node.name.toLowerCase()}`}return node.name}
function nodeById(id){return state.nodes.find(n=>n.id===id)}
function childrenOf(id){return state.nodes.filter(n=>n.parentId===id)}
function colorOf(node){return state.colors[node.id]||node.initialColor||'#efe8df'}
function displayName(n){if(n.level==='species')return scientific(n);return n.level==='genus'?`${n.name} spp.`:n.name}
function pathValue(node,key){return node.path.find(x=>x.level===key)?.name||''}
function sourceTrace(n){return Object.entries(n.fieldSources||{}).flatMap(([field,sources])=>sources.map(s=>`${FIELD_LABELS[field]||field}: ${s.document}${s.pages?.length?` (p. ${s.pages.join(', ')})`:''}${s.worksheet?` (${s.worksheet}, fila ${s.row})`:''}`)).join('\n')}
function fieldValue(n,key){if(TAXON_FIELDS.includes(key))return key==='species'?n.name:pathValue(n,key); if(key==='level')return ({granGroup:'Gran grupo',group:'Grupo',subgroup:'Subgrupo',family:'Familia',subfamily:'Subfamilia',genus:'Género',species:'Especie'})[n.level];if(key==='sourceTrace')return sourceTrace(n);return n.fields?.[key]||''}

function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{r.result.createObjectStore(STORE);r.result.createObjectStore(BLOB_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbGet(key){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(key,value){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).put(value,key);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function blobPut(key,value){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(BLOB_STORE,'readwrite').objectStore(BLOB_STORE).put(value,key);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function blobGet(key){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(BLOB_STORE).objectStore(BLOB_STORE).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function blobDelete(key){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(BLOB_STORE,'readwrite').objectStore(BLOB_STORE).delete(key);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function allBlobs(){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(BLOB_STORE).objectStore(BLOB_STORE).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}

function mergeInitialSeed(){let added=0;const byId=new Map(state.nodes.map(n=>[n.id,n]));for(const incoming of seed.nodes){const current=byId.get(incoming.id);if(!current){state.nodes.push(incoming);byId.set(incoming.id,incoming);added++;continue}current.fields={...(incoming.fields||{}),...(current.fields||{})};current.fieldSources=Object.fromEntries([...new Set([...Object.keys(incoming.fieldSources||{}),...Object.keys(current.fieldSources||{})])].map(k=>[k,[...(incoming.fieldSources?.[k]||[]),...(current.fieldSources?.[k]||[])]].filter((v,i,a)=>i===a.findIndex(x=>JSON.stringify(x)===JSON.stringify(v)))));current.notes=[...(incoming.notes||[]),...(current.notes||[])].filter((v,i,a)=>i===a.findIndex(x=>JSON.stringify(x)===JSON.stringify(v)));current.sourceRows=[...new Set([...(incoming.sourceRows||[]),...(current.sourceRows||[])])];if(!current.initialColor)current.initialColor=incoming.initialColor}state.seedSchemaVersion=seed.schemaVersion;return added}
async function initialise(){seed=await fetch('./data/seed.json').then(r=>r.json());state=await dbGet('state');if(!state){state={nodes:seed.nodes,tags:[],colors:{},recentColors:[],favoriteColors:[],images:[],history:[],settings:{firestore:null,lastSync:null},seedSchemaVersion:seed.schemaVersion};await persist(false)}else if(state.seedSchemaVersion!==seed.schemaVersion){const added=mergeInitialSeed();await persist(false);setTimeout(()=>toast(`Base inicial actualizada: ${added} fichas nuevas; tus ediciones locales se conservaron.`),250)}currentId=state.nodes.find(n=>n.level==='species')?.id||state.nodes.find(n=>n.level==='genus')?.id;$('#sidebarCount').textContent=`${state.nodes.length} fichas`;bindShell();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}
async function persist(sync=true){state.updatedAt=now();await dbPut('state',state);if(sync&&cloud)await syncCloud().catch(()=>toast('No se pudo sincronizar Firestore ahora'))}
function remember(change){state.history.unshift({...change,at:now()});state.history=state.history.slice(0,40)}
async function mutate(change){remember(change);await persist();render()}

function bindShell(){
  $$('.nav-link').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;$$('.nav-link').forEach(x=>x.classList.toggle('active',x===b));render()});
  $('#editMode').onchange=e=>{state.editMode=e.target.checked;$('#modeLabel').textContent=e.target.checked?'Modo edición':'Modo consulta';render()};
  $('#globalSearch').oninput=e=>{filters.tableSearch=e.target.value;currentView='table';$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='table'));render()};
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&state.editMode){e.preventDefault();undoLast()}});
  $('#filePicker').onchange=e=>uploadImages([...e.target.files]);$('#importPicker').onchange=e=>importFile(e.target.files[0]);
}
function render(){$('#editMode').checked=!!state.editMode;$('#modeLabel').textContent=state.editMode?'Modo edición':'Modo consulta';$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===currentView));({atlas:renderAtlas,table:renderTable,gallery:renderGallery,review:renderReview,settings:renderSettings})[currentView]();}
function crumbs(n){return `<div class="crumbs"><button data-open="home">Inicio</button>${n.path.map(p=>`<i>›</i><button data-open-path="${escapeHtml(p.level)}">${escapeHtml(p.name)}</button>`).join('')}</div>`}
function renderAtlas(){const host=$('#atlas'),n=nodeById(currentId)||state.nodes[0];if(!n){host.innerHTML='<div class="empty-state">No hay datos.</div>';return}const kids=childrenOf(n.id), fields=Object.entries(FIELD_LABELS).filter(([k])=>n.fields?.[k]||state.editMode);host.innerHTML=`${crumbs(n)}<div class="title-row"><div><h1 class="scientific-title" data-name="${n.id}">${escapeHtml(displayName(n))}</h1><p class="subtitle">${fieldValue(n,'level')} · información propia del nivel seleccionado</p></div><div class="toolbar"><button class="button" id="compareBtn">Comparar</button><button class="button ${state.editMode?'primary':''}" id="addChildBtn">Añadir ficha</button></div></div><div class="badge-row">${n.path.map(p=>`<button class="tag" data-open-path="${p.level}">${escapeHtml(p.name)}</button>`).join('')}${state.tags.filter(t=>n.tags?.includes(t.id)).map(t=>`<button class="tag editable" data-tag="${t.id}">#${escapeHtml(t.name)} ×</button>`).join('')}${state.editMode?'<button class="tag add-tag" id="addTag">＋ Etiqueta</button>':''}</div><div class="detail-grid"><div class="card"><p class="edit-hint">${state.editMode?'Doble clic sobre un texto para editarlo. Ctrl+Z deshace el último cambio.':'Activá el modo edición para modificar datos.'}</p><div class="data-sections">${fields.map(([k,label])=>fieldCard(n,k,label)).join('')||'<div class="empty-state">Esta ficha todavía no tiene atributos propios. El contexto de la jerarquía está a la derecha.</div>'}</div>${renderImages(n)}</div><aside class="card facts"><h2>Información taxonómica</h2><dl>${n.path.map(p=>`<div><dt>${FIELD_LABELS[p.level]||({granGroup:'Gran grupo',group:'Grupo',subgroup:'Subgrupo',family:'Familia',subfamily:'Subfamilia',genus:'Género',species:'Especie'})[p.level]}</dt><dd class="taxon-inline" data-taxonomy="${p.level}">${p.level==='species'?`<em>${escapeHtml(scientific(n))}</em>`:escapeHtml(p.name)}</dd></div>`).join('')}</dl><hr><h3>${kids.length?'Incluye':'Contexto'}</h3>${kids.length?`<div class="taxon-list">${kids.map(c=>`<button data-open="${c.id}"><span>${c.level==='genus'||c.level==='species'?`<em>${escapeHtml(displayName(c))}</em>`:escapeHtml(c.name)}</span><small>${fieldValue(c,'level')}</small></button>`).join('')}</div>`:renderContext(n)}</aside></div>`;bindDynamic(host)}
function fieldCard(n,k,label){const v=n.fields?.[k]||'';const split=k==='importance'&&v.includes(';');return `<article class="field-card ${['description','observations','morphologyGeneral'].includes(k)?'wide':''}"><div class="field-label">${label}</div><div class="field-value ${!v?'empty-edit':''}" data-field="${k}" data-node="${n.id}">${split?`<div class="split-items">${v.split(';').filter(Boolean).map(x=>`<span>${escapeHtml(x.trim())}</span>`).join('')}</div>`:escapeHtml(v||'Doble clic para agregar contenido')}</div></article>`}
function renderContext(n){const ancestors=n.path.slice(0,-1).map(p=>state.nodes.find(x=>x.id===n.path.slice(0,n.path.indexOf(p)+1).map(q=>`${q.level}:${slug(q.name)}`).join('/'))).filter(Boolean).reverse();return ancestors.length?`<div class="taxon-list">${ancestors.slice(0,2).map(a=>`<button data-open="${a.id}"><span>${escapeHtml(a.name)}</span><small>${fieldValue(a,'level')}</small></button>`).join('')}</div>`:'<p class="subtitle">No hay nivel superior.</p>'}
function renderImages(n){const imgs=state.images.filter(i=>i.nodeId===n.id);return `<section class="card" style="margin-top:14px"><h2>Galería de imágenes</h2><div class="gallery-strip">${imgs.map(i=>`<button class="image-tile" data-image="${i.id}">${i.primary?'<b class="primary">Principal</b>':''}<img data-blob="${i.id}" alt="${escapeHtml(i.title||'Imagen de estudio')}"><span>${escapeHtml(i.title||i.type)}</span></button>`).join('')}${state.editMode?'<button class="image-tile image-add" id="addImage">＋<br>Subir imágenes<br><small>o arrastrar aquí</small></button>':''}</div></section>`}
function bindDynamic(host){
  $$('[data-open]',host).forEach(b=>b.onclick=()=>{if(b.dataset.open==='home'){currentId=state.nodes[0].id}else{currentId=b.dataset.open}render()});$$('[data-open-path]',host).forEach(b=>b.onclick=()=>{const n=nodeById(currentId);const part=n.path.find(p=>p.level===b.dataset.openPath);const idx=n.path.indexOf(part);const id=n.path.slice(0,idx+1).map(p=>`${p.level}:${slug(p.name)}`).join('/');currentId=id;render()});
  $$('.field-value',host).forEach(el=>el.ondblclick=()=>editField(el));$('.scientific-title',host)?.addEventListener('dblclick',()=>editName(n));$$('.taxon-inline',host).forEach(el=>el.ondblclick=()=>editTaxon(n,el.dataset.taxonomy));
  $('#addTag',host)?.addEventListener('click',()=>tagModal(n));$$('[data-tag]',host).forEach(b=>b.onclick=()=>state.editMode&&removeTag(n,b.dataset.tag));$('#addImage',host)?.addEventListener('click',()=>{$('#filePicker').dataset.node=n.id;$('#filePicker').click()});$('#addChildBtn',host)?.addEventListener('click',()=>state.editMode?childModal(n):toast('Activá el modo edición para añadir una ficha'));$('#compareBtn',host)?.addEventListener('click',()=>comparisonModal(n));
  $$('.image-tile[data-image]',host).forEach(b=>b.onclick=()=>imageModal(state.images.find(i=>i.id===b.dataset.image)));loadImages(host);
  const dz=$('.image-add',host);if(dz){['dragenter','dragover'].forEach(e=>dz.addEventListener(e,x=>{x.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(e=>dz.addEventListener(e,x=>{x.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>uploadImages([...e.dataTransfer.files],n.id))}
}
async function loadImages(scope=document){for(const img of $$('img[data-blob]',scope)){const blob=await blobGet(img.dataset.blob);if(blob)img.src=URL.createObjectURL(blob)}}
async function editField(el){if(!state.editMode)return;const n=nodeById(el.dataset.node),key=el.dataset.field,old=n.fields?.[key]||'';el.contentEditable='true';el.textContent=old;el.focus();const save=async()=>{el.contentEditable='false';const value=el.textContent.trim();if(value!==old){n.fields[key]=value;await mutate({type:'field',id:n.id,key,from:old,to:value});toast('Cambio guardado')}};el.onblur=save;el.onkeydown=e=>{if(e.key==='Escape'){el.textContent=old;el.blur()}if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();el.blur()}}}
async function editName(n){if(!state.editMode)return;const v=prompt('Nombre de esta ficha:',n.name);if(v&&v.trim()!==n.name){const old=n.name;n.name=v.trim();const piece=n.path.find(p=>p.level===n.level);piece.name=n.name;await mutate({type:'name',id:n.id,from:old,to:n.name});toast('Nombre actualizado')}}
async function editTaxon(n,level){if(!state.editMode)return;const piece=n.path.find(p=>p.level===level),v=prompt(`Editar ${level}:`,piece.name);if(v&&v.trim()!==piece.name){const old=piece.name;piece.name=v.trim();if(level===n.level)n.name=piece.name;await mutate({type:'taxonomy',id:n.id,level,from:old,to:piece.name});toast('Clasificación actualizada')}}
async function removeTag(n,id){n.tags=(n.tags||[]).filter(x=>x!==id);await mutate({type:'tag-remove',id:n.id,tag:id});toast('Etiqueta quitada')}

function rows(){const q=filters.tableSearch.toLowerCase().trim();return state.nodes.filter(n=>{const blob=[n.name,scientific(n),...n.path.map(p=>p.name),...Object.values(n.fields||{}),...(n.tags||[]).map(id=>state.tags.find(t=>t.id===id)?.name||'')].join(' ').toLowerCase();return (!q||blob.includes(q))&&(filters.group==='all'||pathValue(n,'group')===filters.group)&&(filters.level==='all'||n.level===filters.level)}).sort((a,b)=>{const av=fieldValue(a,sort.key)||scientific(a),bv=fieldValue(b,sort.key)||scientific(b);return String(av).localeCompare(String(bv),'es')*sort.dir})}
function renderTable(){const host=$('#table'),groups=[...new Set(state.nodes.map(n=>pathValue(n,'group')).filter(Boolean))];host.innerHTML=`<div class="title-row"><div><h1 class="table-title">Tabla taxonómica</h1><p class="subtitle">Clasificación y todos los atributos cargados; desplazá horizontalmente para verlos.</p></div><button class="button" id="tableCompare">Comparar selección</button></div><div class="toolbar"><input id="tableSearch" value="${escapeHtml(filters.tableSearch)}" placeholder="Buscar en la tabla…"><select id="groupFilter"><option value="all">Todos los grupos</option>${groups.map(x=>`<option ${filters.group===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><select id="levelFilter"><option value="all">Todos los niveles</option>${['family','subfamily','genus','species'].map(x=>`<option value="${x}" ${filters.level===x?'selected':''}>${x}</option>`).join('')}</select><button id="colorTable">Personalizar colores</button></div><div class="table-wrap"><table class="taxonomy-table"><thead><tr>${COLUMNS.map(([k,l])=>`<th data-sort="${k}">${l} ${sort.key===k?(sort.dir===1?'↑':'↓'):''}</th>`).join('')}</tr></thead><tbody>${rows().map(n=>`<tr data-row="${n.id}" class="${n.id===currentId?'selected':''}">${COLUMNS.map(([k])=>`<td data-cell="${k}" data-node="${n.id}">${tableCell(n,k)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${COLUMNS.length}">Sin resultados.</td></tr>`}</tbody></table></div>`;$('#tableSearch').oninput=e=>{filters.tableSearch=e.target.value;renderTable()};$('#groupFilter').onchange=e=>{filters.group=e.target.value;renderTable()};$('#levelFilter').onchange=e=>{filters.level=e.target.value;renderTable()};$$('[data-sort]',host).forEach(th=>th.onclick=()=>{sort={key:th.dataset.sort,dir:sort.key===th.dataset.sort?-sort.dir:1};renderTable()});$$('tr[data-row]',host).forEach(tr=>tr.onclick=e=>{if(e.target.closest('[contenteditable]'))return;currentId=tr.dataset.row;currentView='atlas';$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='atlas'));render()});$$('td[data-cell]',host).forEach(td=>td.ondblclick=e=>editTableCell(e,td));$('#colorTable').onclick=()=>colorModal() ;$('#tableCompare').onclick=()=>comparisonModal()}
function tableCell(n,k){const v=fieldValue(n,k);if(k==='level')return `<span class="color-dot" style="background:${colorOf(n)}"></span>${escapeHtml(v)}`;if(k==='genus')return v?`<em>${escapeHtml(n.level==='genus'?displayName(n):v)}</em>`:'';if(k==='species')return v?`<em>${escapeHtml(scientific(n))}</em>`:'';return escapeHtml(v)}
async function editTableCell(e,td){if(!state.editMode)return;const n=nodeById(td.dataset.node),key=td.dataset.cell;if(['level',...TAXON_FIELDS].includes(key)){toast('Editá ese dato desde la ficha para conservar la ruta');return}const old=n.fields[key]||'';td.contentEditable='true';td.textContent=old;td.focus();const done=async()=>{td.contentEditable='false';const value=td.textContent.trim();if(value!==old){n.fields[key]=value;await mutate({type:'field',id:n.id,key,from:old,to:value})}};td.onblur=done;td.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();td.blur()}}}

function renderGallery(){const host=$('#gallery'),types=[...new Set(state.images.map(i=>i.type))];const imgs=state.images.filter(i=>filters.galleryType==='all'||i.type===filters.galleryType);host.innerHTML=`<h1 class="table-title">Galería</h1><div class="toolbar"><select id="galleryFilter"><option value="all">Todos los tipos</option>${types.map(t=>`<option ${t===filters.galleryType?'selected':''}>${escapeHtml(t)}</option>`).join('')}</select>${state.editMode?'<button class="primary" id="galleryUpload">Subir imágenes</button>':''}</div><div class="image-gallery">${imgs.map(i=>`<button class="image-tile" data-image="${i.id}">${i.primary?'<b class="primary">Principal</b>':''}<img data-blob="${i.id}" alt="${escapeHtml(i.title||i.type)}"><span>${escapeHtml(i.title||i.type)} · ${escapeHtml(displayName(nodeById(i.nodeId)||{name:'Ficha'}))}</span></button>`).join('')||'<div class="empty-state">Todavía no hay imágenes cargadas.</div>'}</div>`;$('#galleryFilter').onchange=e=>{filters.galleryType=e.target.value;renderGallery()};$('#galleryUpload')?.addEventListener('click',()=>{$('#filePicker').dataset.node=currentId;$('#filePicker').click()});$$('[data-image]',host).forEach(b=>b.onclick=()=>imageModal(state.images.find(i=>i.id===b.dataset.image)));loadImages(host)}
function renderReview(){const host=$('#review');host.innerHTML=`<h1 class="table-title">Revisión de fuentes</h1><p class="subtitle">No se consolidaron datos ni se corrigieron grafías automáticamente.</p><div class="card"><div class="notice">Base: ${escapeHtml(seed.source.workbook)}, hoja ${escapeHtml(seed.source.worksheet)}. Los atributos extraídos de los apuntes conservan documento y página en la semilla y en la exportación XLSX; las menciones sin atributos siguen diferenciadas.</div></div><div class="review-list" style="margin-top:14px">${seed.issues.map(i=>`<div class="review-item"><strong>Revisión pendiente</strong><br>${escapeHtml(i.message)}<div class="toolbar">${i.nodeIds.map(id=>`<button class="button small" data-review-open="${id}">Abrir ficha</button>`).join('')}</div></div>`).join('')||'<div class="empty-state">No hay discrepancias detectadas.</div>'}</div>`;$$('[data-review-open]',host).forEach(b=>b.onclick=()=>{currentId=b.dataset.reviewOpen;currentView='atlas';render()})}
function renderSettings(){const host=$('#settings'),recent=[...new Set([...state.recentColors||[],...state.favoriteColors||[]])];host.innerHTML=`<h1 class="table-title">Configuración y respaldo</h1><div class="settings-grid"><article class="card"><h2>Datos y backups</h2><p>Exportá los datos, la configuración y las imágenes locales. El backup se restaura en otro navegador o equipo.</p><div class="toolbar"><button id="backupBtn" class="primary">Crear backup .zip</button><button id="exportJson">Exportar JSON</button><button id="importBtn">Importar / restaurar</button></div><p class="subtitle">La importación XLSX suma atributos sin sobrescribir ediciones ya realizadas.</p></article><article class="card"><h2>Exportación XLSX</h2><p>La planilla preserva encabezados y usa colores por categoría; los bordes separan principalmente géneros.</p><button id="xlsxBtn" class="button primary">Exportar XLSX</button></article><article class="card"><h2>Colores</h2><p>Color de la ficha actual: <strong>${escapeHtml(displayName(nodeById(currentId)||state.nodes[0]))}</strong></p><div class="color-row"><input type="color" id="quickColor" value="${colorOf(nodeById(currentId)||state.nodes[0])}"><button id="favoriteColor">Guardar como favorito</button></div><div class="recent-colors">${recent.map(c=>`<button class="swatch" data-swatch="${c}" style="background:${c}" title="${c}"></button>`).join('')||'<small>Los colores usados aparecerán aquí.</small>'}</div></article><article class="card"><h2>Sincronización Firestore</h2><p>${state.settings.firestore?'Configuración guardada. Las fichas y preferencias se sincronizan; las imágenes siguen siendo locales y viajan en el backup.':'No configurada. Se conecta únicamente si creás un proyecto Firebase en el plan Spark gratuito.'}</p><div class="toolbar"><button id="firebaseBtn">${state.settings.firestore?'Reconfigurar':'Configurar Firestore'}</button>${state.settings.firestore?'<button id="cloudSync">Sincronizar ahora</button>':''}</div></article><article class="card"><h2>Historial reciente</h2><p>${state.history.length?`${state.history.length} cambios locales disponibles. El último puede deshacerse con Ctrl+Z en modo edición.`:'Sin cambios locales todavía.'}</p><button id="undoBtn" class="button">Deshacer último cambio</button></article></div>`;$('#backupBtn').onclick=backupZip;$('#exportJson').onclick=exportJson;$('#importBtn').onclick=()=>$('#importPicker').click();$('#xlsxBtn').onclick=exportXlsx;$('#quickColor').onchange=e=>setColor(e.target.value);$('#favoriteColor').onclick=()=>{const c=colorOf(nodeById(currentId)||state.nodes[0]);state.favoriteColors=[...new Set([...state.favoriteColors,c])];persist();renderSettings();toast('Color favorito guardado')};$$('[data-swatch]',host).forEach(b=>b.onclick=()=>setColor(b.dataset.swatch));$('#firebaseBtn').onclick=firebaseModal;$('#cloudSync')?.addEventListener('click',()=>syncCloud());$('#undoBtn').onclick=undoLast}
async function setColor(color){const n=nodeById(currentId)||state.nodes[0];state.colors[n.id]=color;state.recentColors=[color,...(state.recentColors||[]).filter(x=>x!==color)].slice(0,12);await mutate({type:'color',id:n.id,to:color});toast('Color guardado')}

function modal(html){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal">${html}</div></div>`;$('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};$$('[data-close-modal]').forEach(b=>b.onclick=closeModal)}function closeModal(){$('#modalRoot').innerHTML=''}
function tagModal(n){modal(`<h2>Etiquetas</h2><div class="toolbar">${state.tags.map(t=>`<button class="tag" data-tag-toggle="${t.id}">#${escapeHtml(t.name)} ${n.tags?.includes(t.id)?'✓':''}</button>`).join('')||'<span class="subtitle">No hay etiquetas.</span>'}</div><label>Nueva etiqueta<input id="newTag" placeholder="Ej.: zoonótica"></label><div class="modal-actions"><button class="button" data-close-modal>Cancelar</button><button id="saveTag" class="button primary">Guardar</button></div>`);$$('[data-tag-toggle]').forEach(b=>b.onclick=async()=>{const id=b.dataset.tagToggle;n.tags=n.tags||[];n.tags.includes(id)?n.tags=n.tags.filter(x=>x!==id):n.tags.push(id);await mutate({type:'tag',id:n.id,tag:id});tagModal(n)});$('#saveTag').onclick=async()=>{const name=$('#newTag').value.trim();if(!name)return;let t=state.tags.find(x=>x.name.toLowerCase()===name.toLowerCase());if(!t){t={id:`tag-${crypto.randomUUID()}`,name};state.tags.push(t)}n.tags=[...new Set([...(n.tags||[]),t.id])];await mutate({type:'tag-add',id:n.id,tag:t.id});closeModal();toast('Etiqueta guardada')}}
function childModal(parent){const options=parent.level==='family'?['subfamily','genus']:parent.level==='subfamily'?['genus']:parent.level==='genus'?['species']:[];if(!options.length){toast('Esta ficha no admite un nivel inferior en esta versión');return}modal(`<h2>Añadir ficha</h2><div class="form-grid"><label>Nivel<select id="childLevel">${options.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Nombre<input id="childName" placeholder="Nombre científico"></label></div><div class="modal-actions"><button class="button" data-close-modal>Cancelar</button><button id="saveChild" class="button primary">Crear ficha</button></div>`);$('#saveChild').onclick=async()=>{const level=$('#childLevel').value,name=$('#childName').value.trim();if(!name)return;const path=[...parent.path,{level,name:level==='species'?name.toLowerCase():name}],id=parent.id+`/${level}:${slug(name)}`;if(nodeById(id)){toast('Ya existe esa ficha');return}const node={id,level,name:level==='species'?name.toLowerCase():name,parentId:parent.id,path,fields:{},tags:[],notes:[],sourceRows:[],initialColor:'',createdFrom:'app'};state.nodes.push(node);currentId=id;await mutate({type:'create',id});closeModal();toast('Ficha creada')}}
function comparisonModal(base){const candidates=state.nodes.filter(n=>['genus','species'].includes(n.level));modal(`<h2>Comparar registros</h2><p class="subtitle">Elegí hasta cuatro fichas para ver sus campos en paralelo.</p><select id="comparePick" multiple size="10" style="width:100%">${candidates.map(n=>`<option value="${n.id}" ${base&&n.id===base.id?'selected':''}>${escapeHtml(displayName(n))}</option>`).join('')}</select><div class="modal-actions"><button class="button" data-close-modal>Cerrar</button><button id="runCompare" class="button primary">Comparar</button></div>`);$('#runCompare').onclick=()=>{const selected=[...$('#comparePick').selectedOptions].slice(0,4).map(o=>nodeById(o.value));if(!selected.length)return;modal(`<h2>Comparación</h2><div class="table-wrap"><table class="taxonomy-table"><thead><tr><th>Campo</th>${selected.map(n=>`<th><em>${escapeHtml(displayName(n))}</em></th>`).join('')}</tr></thead><tbody>${['morphologyGeneral','morphologyMale','morphologyFemale','egg','ppp','definitiveHost','location','infectiveForm','importance'].map(k=>`<tr><td><strong>${FIELD_LABELS[k]}</strong></td>${selected.map(n=>`<td>${escapeHtml(n.fields[k]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="button" data-close-modal>Cerrar</button></div>`)}}
async function uploadImages(files,nodeId=$('#filePicker').dataset.node||currentId){if(!files?.length)return;for(const file of files.filter(f=>f.type.startsWith('image/'))){const id=`img-${crypto.randomUUID()}`;await blobPut(id,file);state.images.push({id,nodeId,type:'otro',title:file.name.replace(/\.[^.]+$/,''),description:'',primary:!state.images.some(x=>x.nodeId===nodeId),mime:file.type,createdAt:now()})}await mutate({type:'image-add',nodeId,count:files.length});$('#filePicker').value='';toast(`${files.length} imagen(es) guardada(s) localmente`) }
async function imageModal(image){const n=nodeById(image.nodeId);modal(`<h2>${escapeHtml(image.title||'Imagen')}</h2><div class="lightbox"><img data-blob="${image.id}" alt="${escapeHtml(image.title||'Imagen')}"><div class="form-grid"><label>Tipo<select id="imgType">${['adulto','macho','hembra','huevo','larva','extremo anterior','extremo posterior','lesión','ciclo','preparado','esquema','otro'].map(x=>`<option ${x===image.type?'selected':''}>${x}</option>`).join('')}</select></label><label>Título<input id="imgTitle" value="${escapeHtml(image.title||'')}"></label></div><label>Descripción<textarea id="imgDesc">${escapeHtml(image.description||'')}</textarea></label></div><div class="modal-actions">${state.editMode?`<button id="deleteImg" class="button danger">Eliminar</button><button id="mainImg" class="button">${image.primary?'Imagen principal':'Marcar principal'}</button><button id="saveImg" class="button primary">Guardar</button>`:''}<button class="button" data-close-modal>Cerrar</button></div>`);loadImages($('#modalRoot'));if(state.editMode){$('#saveImg').onclick=async()=>{Object.assign(image,{type:$('#imgType').value,title:$('#imgTitle').value.trim(),description:$('#imgDesc').value.trim()});await mutate({type:'image-meta',id:image.id});closeModal();toast('Imagen actualizada')};$('#mainImg').onclick=async()=>{state.images.filter(x=>x.nodeId===image.nodeId).forEach(x=>x.primary=x.id===image.id);await mutate({type:'image-main',id:image.id});closeModal();toast('Imagen principal actualizada')};$('#deleteImg').onclick=async()=>{if(!confirm('¿Eliminar esta imagen local?'))return;state.images=state.images.filter(x=>x.id!==image.id);await blobDelete(image.id);await mutate({type:'image-delete',id:image.id});closeModal();toast('Imagen eliminada')}}}
function colorModal(){modal(`<h2>Personalizar color</h2><p>El color se guarda para la ficha seleccionada y queda disponible entre los recientes.</p><input id="modalColor" type="color" value="${colorOf(nodeById(currentId)||state.nodes[0])}"><div class="modal-actions"><button class="button" data-close-modal>Cancelar</button><button id="saveColorModal" class="button primary">Guardar</button></div>`);$('#saveColorModal').onclick=()=>{setColor($('#modalColor').value);closeModal()}}

async function undoLast(){const h=state.history.shift();if(!h){toast('No hay cambios para deshacer');return}const n=nodeById(h.id);if(h.type==='field'&&n)n.fields[h.key]=h.from||'';if(h.type==='color')delete state.colors[h.id];if(h.type==='tag-add'&&n)n.tags=n.tags.filter(x=>x!==h.tag);if(h.type==='tag-remove'&&n)n.tags.push(h.tag);if(h.type==='create')state.nodes=state.nodes.filter(x=>x.id!==h.id);await persist();render();toast('Último cambio deshecho')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function loadScript(src){if(document.querySelector(`script[src="${src}"]`))return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s)})}
async function exportJson(){download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'atlas-parasitologia-datos.json');toast('Datos exportados')}
async function backupZip(){try{await loadScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js');const zip=new JSZip();zip.file('atlas-parasitologia-datos.json',JSON.stringify(state,null,2));for(const img of state.images){const blob=await blobGet(img.id);if(blob)zip.file(`images/${img.id}`,blob)}download(await zip.generateAsync({type:'blob'}),'atlas-parasitologia-backup.zip');toast('Backup creado')}catch{toast('No se pudo crear el ZIP. Verificá la conexión a Internet.')}}
async function exportXlsx(){try{await loadScript('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js');const data=state.nodes.map(n=>Object.fromEntries(EXPORT_COLUMNS.map(([k,l])=>[l,fieldValue(n,k)]))),ws=XLSX.utils.json_to_sheet(data);ws['!cols']=EXPORT_COLUMNS.map(([k,l])=>({wch:['morphologyGeneral','morphologyMale','morphologyFemale','cycle','egg','sourceTrace'].includes(k)?48:Math.max(16,l.length+3)}));ws['!rows']=state.nodes.map(()=>({hpt:54}));EXPORT_COLUMNS.forEach(([,label],c)=>{const cell=ws[XLSX.utils.encode_cell({r:0,c})];cell.s={font:{bold:true,color:{rgb:'FFFFFF'}},fill:{fgColor:{rgb:'4B1016'}},alignment:{wrapText:true,vertical:'center'}}});state.nodes.forEach((n,r)=>{EXPORT_COLUMNS.forEach(([,],c)=>{const cell=ws[XLSX.utils.encode_cell({r:r+1,c})];if(!cell)return;cell.s={alignment:{wrapText:true,vertical:'top'},border:{bottom:{style:n.level==='genus'?'thin':'hair',color:{rgb:n.level==='genus'?'B58A4A':'E5DDD3'}}}};if(c===0)cell.s.fill={fgColor:{rgb:colorOf(n).replace('#','').toUpperCase()}}})});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Atlas');XLSX.writeFile(wb,'atlas-parasitologia.xlsx');toast('XLSX exportado con todos los campos y fuentes')}catch{toast('No se pudo exportar XLSX. Verificá la conexión a Internet.')}}
async function importFile(file){if(!file)return;try{if(file.name.endsWith('.zip')){await loadScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js');const zip=await JSZip.loadAsync(file),raw=await zip.file('atlas-parasitologia-datos.json').async('string');state=JSON.parse(raw);for(const im of state.images){const f=zip.file(`images/${im.id}`);if(f)await blobPut(im.id,await f.async('blob'))}await persist();render();toast('Backup restaurado');return}if(file.name.endsWith('.json')){state=JSON.parse(await file.text());await persist();render();toast('Datos restaurados');return}if(file.name.endsWith('.xlsx')){await loadScript('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),data=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});importXlsxRows(data);await persist();render();toast('XLSX incorporado sin sobrescribir ediciones');return}}catch(err){console.error(err);toast('No se pudo importar ese archivo')}finally{$('#importPicker').value=''}}
function importXlsxRows(rows){const aliases={"GRAN GRUPO":'granGroup',"GRUPO":'group',"SUBGRUPO":'subgroup',"FAMILIA":'family',"SUBFAMILIA":'subfamily',"GÉNERO":'genus',"GENERO":'genus',"ESPECIE":'species',"NOMBRE VULGAR":'commonName',"IMPORTANCIA":'importance',"LOCALIZACIÓN":'location',"HOSPEDADOR DEFINITIVO":'definitiveHost',"CICLO":'cycle',"PPP":'ppp',"MORFOLOGÍA GENERAL":'morphologyGeneral',"MORFOLOGÍA MACHO":'morphologyMale',"MORFOLOGÍA HEMBRA":'morphologyFemale',"HUEVO":'egg',"FORMA INFECTANTE":'infectiveForm'};for(const row of rows){const v={};Object.entries(row).forEach(([k,x])=>{const key=aliases[k.toUpperCase().trim()];if(key)v[key]=String(x).trim()});if(!Object.values(v).some(Boolean))continue;let path=[],parentId=null,last=null;for(const level of TAXON_FIELDS){if(!v[level])continue;const name=level==='species'?v[level].toLowerCase():v[level],id=parentId?`${parentId}/${level}:${slug(name)}`:`${level}:${slug(name)}`;let n=nodeById(id);if(!n){n={id,level,name,parentId,path:[...path,{level,name}],fields:{},tags:[],notes:[],sourceRows:[],initialColor:'',createdFrom:'xlsx-import'};state.nodes.push(n)}path=n.path;parentId=id;last=n}if(last)Object.entries(v).filter(([k])=>!TAXON_FIELDS.includes(k)).forEach(([k,x])=>{if(x&&!last.fields[k])last.fields[k]=x;else if(x&&last.fields[k]!==x)last.notes.push({type:'import-conflict',message:`Nueva importación ofrece otro valor para ${k}.`,value:x})})}}

async function firebaseModal(){const old=state.settings.firestore||{};modal(`<h2>Conectar Firestore gratuito</h2><p class="subtitle">Pegá el objeto de configuración web de un proyecto Firebase creado en el plan Spark. No actives facturación ni Firebase Storage.</p><label>Configuración Firebase (JSON)<textarea id="firebaseJson" placeholder='{"apiKey":"…","authDomain":"…","projectId":"…"}'>${escapeHtml(JSON.stringify(old,null,2))}</textarea></label><div class="modal-actions"><button class="button" data-close-modal>Cancelar</button><button id="connectFirebase" class="button primary">Guardar y conectar</button></div>`);$('#connectFirebase').onclick=async()=>{try{state.settings.firestore=JSON.parse($('#firebaseJson').value);await persist(false);await connectFirestore();closeModal();render();toast('Firestore conectado')}catch{toast('La configuración no es JSON válido o no se pudo conectar')}}}
async function connectFirestore(){const cfg=state.settings.firestore;if(!cfg?.projectId)return;const {initializeApp}=await import('https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js');const {getFirestore,doc,getDoc,setDoc}=await import('https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js');const {getAuth,GoogleAuthProvider,signInWithPopup}=await import('https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js');const app=initializeApp(cfg,`atlas-${cfg.projectId}`),auth=getAuth(app);if(!auth.currentUser)await signInWithPopup(auth,new GoogleAuthProvider());cloud={db:getFirestore(app),doc,getDoc,setDoc,user:auth.currentUser};const remote=await cloud.getDoc(cloud.doc(cloud.db,'atlas','shared'));if(remote.exists()&&remote.data().updatedAt>state.updatedAt){const r=remote.data();state={...state,...r,images:state.images};await persist(false);toast('Datos Firestore más recientes recuperados')} }
async function syncCloud(){if(!cloud)await connectFirestore();if(!cloud){toast('Configurá Firestore primero');return}const data={nodes:state.nodes,tags:state.tags,colors:state.colors,recentColors:state.recentColors,favoriteColors:state.favoriteColors,history:state.history,updatedAt:now(),schemaVersion:1};await cloud.setDoc(cloud.doc(cloud.db,'atlas','shared'),data);state.settings.lastSync=now();await persist(false);toast('Datos de texto sincronizados')}
initialise();
